      "topic": {
        "text": "Escape sequences in Java strings",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "In Java, certain characters like double quotes, backslashes, newlines, and tabs cannot be placed directly inside string literals because the compiler interprets them specially. To include them, you must prefix the character with a backslash (\\) which tells the compiler to treat the following character as a literal part of the string.",
        "refs": ["Q0001", "Q0002", "Q0003", "Q0004"]
      },
      "explanation_type": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "Including double quotes in a string",
        "refs": ["Q0001"]
      },
      "example_text": {
        "text": "String s = \"\\\"Hello Marsh\\\"\"; // prints \"Hello Marsh\"",
        "refs": ["Q0001"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Including a backslash in a Windows file path",
        "refs": ["Q0002", "Q0003"]
      },
      "example_text": {
        "text": "String path = \"C:\\\\Windows\\\\\"; // prints C:\\Windows\\",
        "refs": ["Q0002", "Q0003"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Adding a newline character",
        "refs": ["Q0004"]
      },
      "example_text": {
        "text": "String multiLine = \"C Drive\\nWindows\"; // prints C Drive on first line, Windows on second line",
        "refs": ["Q0004"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "Adding a tab character",
        "refs": ["Q0004"]
      },
      "example_text": {
        "text": "String tabbed = \"C Drive\\tWindows\"; // prints C Drive    Windows (with a tab space)",
        "refs": ["Q0004"]
      },
      "example_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "The four commonly used escape sequences in Java strings are \\\" (double quote), \\\\ (backslash), \\n (newline), and \\t (tab).",
        "refs": ["Q0005"]
      },
      "fact_type": null
    }
  ],
